"""Build model inputs from fetched public data.

Writes config/macro/generated/<ISO2>.yaml with the CPI history and projection
path (IMF World Economic Outlook, average consumer prices) and real GDP growth,
each value tagged with its source. Years up to the year before the fetch are
treated as history; later years as IMF projections. DataMapper does not flag
estimates, so that split is an assumption and is labelled as one.
"""

from __future__ import annotations

import sys
from datetime import date
from pathlib import Path

import yaml

from engine.config import CONFIG_DIR
from engine.external.parse import OUT, load

ISO3 = {"FR": "FRA", "ES": "ESP", "IT": "ITA", "EL": "GRC", "GR": "GRC", "DE": "DEU", "GB": "GBR", "US": "USA", "CA": "CAN"}
GEN = CONFIG_DIR / "macro" / "generated"


def build_country(iso2: str, out: Path = OUT, gen: Path = GEN) -> Path | None:
    iso3 = ISO3.get(iso2)
    cpi, meta = load("imf_pcpipch_long", out)
    if cpi is None or cpi.empty:
        cpi, meta = load("imf_pcpipch", out)
    if cpi is None or cpi.empty or iso3 not in set(cpi["country"]):
        return None
    fetched = meta["fetched_at"][:10]
    split = int(fetched[:4]) - 1                     # last year treated as history
    c = cpi[cpi["country"] == iso3].sort_values("year")
    src = {"publisher": meta["publisher"], "title": meta["title"], "url": meta["url"], "accessed": fetched,
           "sha256": meta["sha256"]}
    doc = {
        "country_iso": iso2,
        "generated": date.today().isoformat(),
        "cpi_history": {
            "measure": "IMF WEO, inflation, average consumer prices (national CPI), annual % change",
            "status": "loaded", "source": src,
            "values": {int(r.year): round(r.value / 100, 6) for r in c.itertuples() if r.year <= split},
        },
        "cpi_projections": {
            "status": "loaded", "source": src,
            "assumption": f"Years after {split} are treated as IMF projections (DataMapper does not flag estimates).",
            "values": [{"year": int(r.year), "rate": round(r.value / 100, 6)} for r in c.itertuples() if r.year > split],
            "beyond_last_year": {"assumption": "Hold the last IMF projection", "rate": None},
            "sampling_sd": 0.008,
        },
    }
    gdp, gmeta = load("imf_ngdp_rpch", out)
    if gdp is not None and not gdp.empty:
        doc["real_gdp_growth"] = {
            "source": {"publisher": gmeta["publisher"], "title": gmeta["title"], "url": gmeta["url"], "accessed": gmeta["fetched_at"][:10]},
            "values": {cc: {int(r.year): round(r.value / 100, 6) for r in gdp[gdp["country"] == cc].itertuples()}
                       for cc in sorted(set(gdp["country"]))},
        }
    gen.mkdir(parents=True, exist_ok=True)
    path = gen / f"{iso2}.yaml"
    path.write_text("# Generated by python -m engine.external.build. Do not edit by hand.\n" +
                    yaml.safe_dump(doc, sort_keys=False, allow_unicode=True), encoding="utf-8")
    return path


def main() -> int:
    countries = sorted({yaml.safe_load(p.read_text())["country_iso"] for p in (CONFIG_DIR / "markets").glob("*.yaml")})
    for iso2 in countries:
        p = build_country(iso2)
        print(iso2, "->", p if p else "no CPI data yet")
    return 0


if __name__ == "__main__":
    sys.exit(main())
